import {GAME} from './config.js';
import {BUILDINGS,UNITS,FIRST_UNIT,MAX_LEVEL,SIZE,RESOURCE_KEYS,CAMP_NAMES,DIFFICULTIES,ALLIES,buildingStats,unitStats} from './catalog.js';
export {BUILDINGS,UNITS,RESOURCE_KEYS,SIZE,buildingStats,unitStats,DIFFICULTIES};
const ok=message=>({ok:true,message}),fail=message=>({ok:false,message}),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const rand=(x,y,seed=1)=>{let n=Math.imul(x+seed,374761393)^Math.imul(y+17,668265263);n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967296;};
export const hqLevel=s=>s.buildings.find(b=>b.type==='hq')?.level||1;
export const builders=s=>2+s.buildings.filter(b=>b.type==='builders'&&b.hp>0&&!b.job).length;
export const usedBuilders=s=>s.buildings.filter(b=>b.job).length;
export const population=s=>s.army.reduce((n,u)=>n+UNITS[u.type].pop,0)+s.training.reduce((n,j)=>n+UNITS[j.type].pop,0)+(s.battle?[...s.battle.reserve,...s.battle.units.filter(u=>u.side==='player'&&u.hp>0)].reduce((n,u)=>n+UNITS[u.type].pop,0):0);
export const populationCap=s=>18+s.buildings.filter(b=>b.type==='house'&&b.hp>0).reduce((n,b)=>n+10+2*(b.level-1),0);
export const storageCap=s=>2200+s.buildings.filter(b=>b.type==='storage'&&b.hp>0).reduce((n,b)=>n+BUILDINGS.storage.storage*b.level,0);
export const unitLevel=(s,id)=>s.research[id]||1;
export function log(s,message){s.log.unshift({time:s.time,message});s.log.length=Math.min(s.log.length,35);}
function credit(s,values){const cap=storageCap(s);for(const k of RESOURCE_KEYS)s.resources[k]=clamp(s.resources[k]+(values[k]||0),0,cap);}
export function affordable(s,cost){return Object.entries(cost).every(([k,v])=>RESOURCE_KEYS.includes(k)&&Number.isFinite(v)&&v>=0&&s.resources[k]>=v);}
function pay(s,cost){for(const[k,v]of Object.entries(cost))s.resources[k]-=v;}
export function buildCost(type,level=1){const spec=BUILDINGS[type],f=level===1?1:Math.pow(1.72,level-1)*.85;return Object.fromEntries(Object.entries(spec.cost).map(([k,v])=>[k,Math.ceil(v*f)]));}
export function duration(type,level=1){return Math.round(BUILDINGS[type].time*(1+(level-1)*1.15));}
export function terrain(x,y,seed){if(x<0||y<0||x>=SIZE||y>=SIZE)return'void';if(x>28||y>29)return'water';if((x<6||y<6||x>24||y>25)&&rand(x,y,seed)<.28)return rand(x+9,y,seed)<.8?'tree':'rock';return'grass';}
export const groundAt=(s,x,y)=>s.cleared.includes(Math.floor(x)+':'+Math.floor(y))?'grass':terrain(Math.floor(x),Math.floor(y),s.seed);
export function createState(seed=(Date.now()>>>0),difficulty='easy'){
 const s={version:1,game:GAME.id,seed:seed>>>0,difficulty:Object.hasOwn(DIFFICULTIES,difficulty)?difficulty:'easy',time:0,serial:1,resources:{gold:1250,wood:1000,supply:700,metal:350},buildings:[],army:[],training:[],research:{},study:null,cleared:[],completed:{},claimed:[],alliances:{},stats:{collected:0,built:0,upgraded:0,trained:0,wins:0,kills:0,lost:0},xp:0,log:[],battle:null,lastBattle:null,nextRaid:600,tutorial:false,settings:{sound:true,volume:.45},savedAt:Date.now()};
 for(const[type,x,y]of[['hq',14,13],['house',11,12],['house',11,16],['goldmine',18,13],['lumber',18,17],['supply',14,18],['storage',14,9],['infantry',9,9],['tower',9,15],['tower',20,11]]){const b={id:'b'+s.serial++,type,x,y,level:1,hp:BUILDINGS[type].hp,stored:0,job:null};s.buildings.push(b);}
 for(let i=0;i<6;i++)s.army.push(makeUnit(s,FIRST_UNIT));log(s,'Tu base está preparada. Recoge recursos, refuerza el ejército y conquista el primer puesto.');return s;
}
export function makeUnit(s,type,level=unitLevel(s,type)){const spec=unitStats(type,level);return{id:'u'+s.serial++,type,level,hp:spec.hp,maxHp:spec.hp,cooldown:0};}
export function collect(s,id){const b=s.buildings.find(x=>x.id===id),spec=b&&BUILDINGS[b.type];if(!spec?.resource||b.hp<=0||b.job)return fail('Este edificio todavía no puede producir.');const value=Math.min(Math.floor(b.stored),storageCap(s)-s.resources[spec.resource]);if(value<1)return fail('La producción necesita tiempo o el almacén está lleno.');s.resources[spec.resource]+=value;b.stored-=value;s.stats.collected+=value;return ok('Recogidos '+value+' de '+GAME.resources[spec.resource].name.toLowerCase()+'.');}
export function collectAll(s){let n=0;for(const b of s.buildings)if(BUILDINGS[b.type].resource){const before=s.stats.collected;collect(s,b.id);n+=s.stats.collected-before;}return n?ok('Recogidos '+Math.floor(n)+' recursos.'):fail('Todavía no hay producción para recoger.');}
export function placement(s,type,x,y,ignore=null){const spec=BUILDINGS[type];if(!spec||!Number.isInteger(x)||!Number.isInteger(y))return fail('Escoge una casilla del terreno.');for(let yy=y;yy<y+spec.size;yy++)for(let xx=x;xx<x+spec.size;xx++){if(groundAt(s,xx,yy)!=='grass')return fail('Necesitas suelo libre. Despeja árboles y rocas primero.');for(const b of s.buildings)if(b.id!==ignore&&xx>=b.x&&xx<b.x+BUILDINGS[b.type].size&&yy>=b.y&&yy<b.y+BUILDINGS[b.type].size)return fail('Aquí ya hay un edificio.');}return ok('Lugar disponible.');}
export function build(s,type,x,y){const spec=BUILDINGS[type];if(s.battle)return fail('Termina la batalla antes de construir.');if(!Object.hasOwn(BUILDINGS,type)||type==='hq')return fail('Ese plano no está disponible.');if(hqLevel(s)<spec.hq)return fail(GAME.hq+' nivel '+spec.hq+' necesario.');if(s.buildings.filter(b=>b.type===type).length>=spec.limit)return fail('Alcanzaste el límite de este edificio.');if(usedBuilders(s)>=builders(s))return fail('Todos los constructores están ocupados.');const p=placement(s,type,x,y);if(!p.ok)return p;if(!affordable(s,spec.cost))return fail('No hay recursos suficientes.');pay(s,spec.cost);s.buildings.push({id:'b'+s.serial++,type,x,y,level:1,hp:spec.hp,stored:0,job:{kind:'build',started:s.time,ends:s.time+duration(type)}});s.stats.built++;log(s,'Obra iniciada: '+spec.name+'.');return ok('Construcción encargada.');}
export function upgradeRequirements(s,b){if(!b)return'Edificio inexistente.';if(b.job)return'Espera a que termine la obra actual.';if(b.hp<=0)return'Reconstruye el edificio primero.';if(b.level>=MAX_LEVEL)return'Nivel máximo alcanzado.';if(b.type!=='hq'&&b.level>=hqLevel(s))return'Mejora '+GAME.hq.toLowerCase()+' al nivel '+(b.level+1)+'.';if(b.type==='hq'){const required=['storage','infantry',...(b.level>=2?['range']:[]),...(b.level>=3?['research','vehicle']:[]),...(b.level>=5?['air']:[])];for(const type of required){const minimum=Math.max(1,b.level-1);if(!s.buildings.some(x=>x.type===type&&x.level>=minimum&&!x.job&&x.hp>0))return BUILDINGS[type].name+' nivel '+minimum+' necesario.';}}return'';}
export function upgradeQuote(s,id){const b=s.buildings.find(x=>x.id===id);if(!b)return{ok:false,message:'Edificio inexistente.'};const next=b.level+1,fully=s.buildings.filter(x=>x.type!=='hq'&&x.hp>0).every(x=>x.level>=b.level&&!x.job),discount=b.type==='hq'&&fully?.2:0,cost=Object.fromEntries(Object.entries(buildCost(b.type,next)).map(([k,v])=>[k,Math.ceil(v*(1-discount))])),message=upgradeRequirements(s,b);return{ok:!message,message,cost,duration:duration(b.type,next),discount,next};}
export function upgrade(s,id){if(s.battle)return fail('Termina la batalla antes de mejorar.');const b=s.buildings.find(x=>x.id===id),q=upgradeQuote(s,id);if(!q.ok)return fail(q.message);if(usedBuilders(s)>=builders(s))return fail('Todos los constructores están ocupados.');if(!affordable(s,q.cost))return fail('No hay recursos suficientes.');pay(s,q.cost);b.job={kind:'upgrade',started:s.time,ends:s.time+q.duration};return ok('Mejora iniciada. La producción de este edificio espera durante la obra.');}
export function moveBuilding(s,id,x,y){const b=s.buildings.find(x=>x.id===id);if(s.battle||!b||b.job)return fail('No puedes moverlo en este momento.');const p=placement(s,b.type,x,y,id);if(!p.ok)return p;b.x=x;b.y=y;return ok('Edificio trasladado.');}
export function repair(s,id){const b=s.buildings.find(x=>x.id===id);if(s.battle||!b||b.job)return fail('No puedes repararlo en este momento.');const max=buildingStats(b.type,b.level).hp;if(b.hp>=max)return fail('No necesita reparaciones.');if(usedBuilders(s)>=builders(s))return fail('Todos los constructores están ocupados.');const emergency=b.hp<=0&&(b.type==='hq'||b.type==='goldmine'),cost={gold:emergency?0:Math.ceil((1-b.hp/max)*70*b.level),wood:emergency?0:Math.ceil((1-b.hp/max)*35*b.level)};if(!affordable(s,cost))return fail('Necesitas recursos para reparar.');pay(s,cost);b.job={kind:'repair',started:s.time,ends:s.time+20+b.level*3};return ok(emergency?'Reconstrucción de emergencia iniciada.':'Reparación iniciada.');}
export function clearTerrain(s,x,y){if(s.battle||!Number.isInteger(x)||!Number.isInteger(y))return fail('No puedes despejar ahora.');const kind=groundAt(s,x,y);if(!['tree','rock'].includes(kind))return fail('Selecciona un árbol o una roca.');if(s.resources.gold<15)return fail('Necesitas 15 de oro para pagar a los trabajadores.');s.resources.gold-=15;s.cleared.push(x+':'+y);credit(s,{[kind==='tree'?'wood':'metal']:45});return ok('Terreno despejado. Recuperaste materiales.');}
export function availableFactory(s,type){const u=UNITS[type];if(!u)return null;return s.buildings.find(b=>b.type===u.factory&&b.level>=u.required&&b.hp>0&&!b.job);}
export function recruit(s,type){const u=UNITS[type];if(!u||hqLevel(s)<u.hq)return fail('Esta tropa aún no está desbloqueada.');const factory=availableFactory(s,type);if(!factory)return fail('Necesitas '+BUILDINGS[u.factory].name+' nivel '+u.required+' operativo.');if(s.training.filter(t=>t.building===factory.id).length>=5)return fail('La cola de este edificio está llena.');if(population(s)+u.pop>populationCap(s))return fail('Construye o mejora viviendas para ampliar el ejército.');if(!affordable(s,u.cost))return fail('Faltan recursos para entrenar.');pay(s,u.cost);const last=s.training.filter(t=>t.building===factory.id).at(-1),start=Math.max(s.time,last?.ends||0);s.training.push({id:'q'+s.serial++,building:factory.id,type,level:unitLevel(s,type),started:start,ends:start+Math.max(5,u.time*(1-(factory.level-1)*.035))});return ok(u.name+' añadido a la cola.');}
export function cancelTraining(s,id){const i=s.training.findIndex(t=>t.id===id);if(i<0)return fail('La orden ya finalizó.');const j=s.training[i],now=s.time;s.training.splice(i,1);credit(s,UNITS[j.type].cost);let end=now;for(const t of s.training.filter(t=>t.building===j.building)){const duration=t.ends-t.started;t.started=Math.max(now,end);t.ends=t.started+duration;end=t.ends;}return ok('Entrenamiento cancelado y coste devuelto.');}
export function researchQuote(s,type){const u=UNITS[type],level=unitLevel(s,type),cost=u?{gold:Math.round(160*level*(u.hq+1)),metal:Math.round(55*level*u.hq),supply:Math.round(80*level)}:{};let message='';const lab=s.buildings.find(b=>b.type==='research'&&b.hp>0&&!b.job);if(!u||hqLevel(s)<u.hq)message='Unidad no desbloqueada.';else if(!lab)message='Construye un laboratorio de investigación.';else if(s.study)message='Hay otra investigación en curso.';else if(level>=5)message='Grado máximo alcanzado.';else if(level>=lab.level||level>=hqLevel(s))message='Mejora el laboratorio al nivel '+(level+1)+'.';return{ok:!message,message,cost,level:level+1,duration:45+level*u?.hq*15};}
export function research(s,type){const q=researchQuote(s,type);if(!q.ok)return fail(q.message);if(!affordable(s,q.cost))return fail('No hay recursos suficientes.');pay(s,q.cost);s.study={type,level:q.level,started:s.time,ends:s.time+q.duration};return ok('Investigación iniciada.');}
export function setDifficulty(s,id){if(!Object.hasOwn(DIFFICULTIES,id))return fail('Dificultad no válida.');if(s.battle)return fail('Cambia la dificultad después de la batalla.');s.difficulty=id;return ok('Dificultad: '+DIFFICULTIES[id].name+'.');}
export function ally(s,id){const a=ALLIES.find(a=>a.id===id);if(!a||!s.buildings.some(b=>b.type==='embassy'&&b.hp>0&&!b.job))return fail('Construye una embajada operativa.');const p=s.alliances[id]||{reputation:0,next:0};if(s.time<p.next)return fail('Esta facción prepara su siguiente encargo.');const amount=120+40*p.reputation;if(s.resources[a.need]<amount)return fail('Reúne '+amount+' de '+GAME.resources[a.need].name+'.');s.resources[a.need]-=amount;p.reputation++;p.next=s.time+300;s.alliances[id]=p;credit(s,{gold:amount*1.5,supply:a.need==='supply'?0:70});s.xp+=40;log(s,'Pacto de suministros con '+a.name+'.');return ok('Encargo cumplido. Reputación '+p.reputation+'.');}
export const QUESTS=[
 {id:'collect',name:'La base se pone en marcha',text:'Recoge 200 recursos de tus productores.',value:s=>s.stats.collected,target:200,reward:{gold:200,wood:120}},
 {id:'build',name:'Una base a tu medida',text:'Construye dos edificios nuevos.',value:s=>s.stats.built,target:2,reward:{gold:220,wood:150,metal:80}},
 {id:'train',name:'Refuerzos para la vanguardia',text:'Completa cuatro entrenamientos.',value:s=>s.stats.trained,target:4,reward:{gold:250,supply:160}},
 {id:'upgrade',name:'Cimientos de un imperio',text:'Completa dos mejoras de edificios.',value:s=>s.stats.upgraded,target:2,reward:{gold:350,wood:220,metal:120}},
 {id:'first',name:'Más allá de la frontera',text:'Consigue tu primera victoria en la campaña.',value:s=>s.stats.wins,target:1,reward:{gold:500,supply:240,metal:140}},
 {id:'command',name:'El siguiente capítulo',text:'Alcanza nivel 3 en el edificio principal.',value:s=>hqLevel(s),target:3,reward:{gold:700,wood:400,metal:250}},
 {id:'veterans',name:'Una fuerza disciplinada',text:'Completa veinte entrenamientos.',value:s=>s.stats.trained,target:20,reward:{gold:900,supply:500,metal:300}},
 {id:'campaign',name:'Maestro de la conquista',text:'Gana seis ataques de campaña.',value:s=>s.stats.wins,target:6,reward:{gold:1300,wood:700,metal:600}}
];
export function claimQuest(s,id){const q=QUESTS.find(q=>q.id===id);if(!q||s.claimed.includes(id)||q.value(s)<q.target)return fail('El encargo aún no se ha completado o ya se cobró.');credit(s,q.reward);s.claimed.push(id);s.xp+=100;return ok('Recompensa recibida.');}
export function tickEconomy(s,dt){const before=s.time;s.time+=dt;for(const b of s.buildings){let active=dt;if(b.job){if(b.job.ends>s.time)continue;active=Math.max(0,s.time-b.job.ends);if(b.job.kind==='upgrade'){b.level++;s.stats.upgraded++;s.xp+=40*b.level;}b.hp=buildingStats(b.type,b.level).hp;b.job=null;log(s,BUILDINGS[b.type].name+' listo · nivel '+b.level+'.');}if(b.hp<=0)continue;const st=buildingStats(b.type,b.level);if(st.rate)b.stored=Math.min(st.capacity,b.stored+st.rate*active);}
 const done=s.training.filter(t=>t.ends<=s.time),pending=s.training.filter(t=>t.ends>s.time);s.training=pending;for(const t of done){const b=s.buildings.find(b=>b.id===t.building);if(b?.hp>0){s.army.push(makeUnit(s,t.type,t.level));s.stats.trained++;s.xp+=12;log(s,UNITS[t.type].name+' listo.');}else credit(s,UNITS[t.type].cost);}
 if(s.study&&s.study.ends<=s.time){const t=s.study;s.research[t.type]=t.level;for(const u of s.army.filter(u=>u.type===t.type)){const ratio=u.hp/u.maxHp;u.level=t.level;u.maxHp=unitStats(u.type,u.level).hp;u.hp=Math.ceil(ratio*u.maxHp);}s.study=null;s.xp+=80;log(s,UNITS[t.type].name+' mejorado al grado '+t.level+'.');}
 if(!s.battle){const hospitals=s.buildings.filter(b=>b.type==='hospital'&&b.hp>0&&!b.job).reduce((n,b)=>n+b.level*1.8,0);for(const u of s.army)u.hp=Math.min(u.maxHp,u.hp+hospitals*dt);}
 return s.time-before;
}
export function camp(s,index){const level=index+1,strength=Math.min(10,Math.ceil(level*.72)),factor=DIFFICULTIES[s.difficulty].damage,seed=s.seed+index*917,b=[];let n=0;
 const add=(type,x,y,l=strength)=>{const st=buildingStats(type,l),f=.38+index*.055;b.push({id:'enemyb'+n++,type,x,y,level:l,hp:Math.round(st.hp*f),maxHp:Math.round(st.hp*f),side:'enemy',attack:Math.round(st.attack*factor*(.6+index*.05)),range:st.range});};add('hq',21,14);add('tower',17,12);if(index>0)add('tower',21,10);if(index>2)add('cannon',18,18);add('goldmine',24,19);add('storage',23,23);if(index>1)add('house',17,23);if(index>3){for(let y=13;y<20;y+=2)add('wall',16,y);}
 const candidates=Object.values(UNITS).filter(u=>u.hq<=Math.max(1,strength)&&!u.heal),enemies=[];for(let i=0;i<Math.min(18,2+index);i++){const type=candidates[Math.floor(rand(i,9,seed)*candidates.length)].id,u=makeUnit({serial:i+1,research:{}},type,1+Math.floor(index/5));Object.assign(u,{id:'enemyu'+i,side:'enemy',x:18+i%4*1.35,y:15+Math.floor(i/4)*1.35,damageScale:factor*.72,order:null});enemies.push(u);}
 return{index,name:CAMP_NAMES[index],level:strength,seed,buildings:b,enemies,reward:{gold:Math.round((350+index*180)*DIFFICULTIES[s.difficulty].reward),wood:200+index*100,supply:180+index*90,metal:80+index*65}};
}
export function startAttack(s,index){if(s.battle)return fail('Ya hay una batalla en marcha.');if(!Number.isInteger(index)||index<0||index>=CAMP_NAMES.length)return fail('Objetivo desconocido.');if(index>0&&!s.completed[index-1])return fail('Conquista el puesto anterior para abrir esta ruta.');if(!s.army.length)return fail('Entrena un ejército primero.');const c=camp(s,index);s.battle={kind:'attack',index,name:c.name,seed:c.seed,elapsed:0,limit:180,buildings:c.buildings,units:c.enemies,reserve:s.army,initialBuildings:c.buildings.length,reward:c.reward,effects:[],serial:0};s.army=[];s.lastBattle=null;return ok('Despliega tropas en la franja azul.');}
export function deploy(s,type,x,y){const b=s.battle;if(!b||b.kind!=='attack')return fail('No hay un ataque abierto.');if(!Number.isFinite(x)||!Number.isFinite(y)||x<2||x>9||y<4||y>28)return fail('Despliega dentro de la franja azul del oeste.');const i=b.reserve.findIndex(u=>u.type===type);if(i<0)return fail('No quedan unidades de este tipo en reserva.');const u=b.reserve.splice(i,1)[0];Object.assign(u,{side:'player',x,y,cooldown:0,order:{kind:'assault',x:20,y:16},path:null});b.units.push(u);return ok(UNITS[type].name+' desplegado.');}
export function deployAll(s){const b=s.battle;if(!b||b.kind!=='attack')return fail('No hay reservas para desplegar.');let i=0;while(b.reserve.length){const type=b.reserve[0].type;deploy(s,type,3+(i%5)*1.05,9+Math.floor(i/5)*.85);i++;}return ok('Ejército desplegado. Selecciona unidades para dar órdenes.');}
export function order(s,ids,x,y,kind='move'){if(!['move','attack','hold'].includes(kind)||!s.battle||!Number.isFinite(x)||!Number.isFinite(y)||x<1||x>30||y<1||y>30)return fail('Orden fuera del campo de batalla.');const list=s.battle.units.filter(u=>u.side==='player'&&u.hp>0&&ids.includes(u.id));if(!list.length)return fail('Selecciona tropas primero.');list.forEach((u,i)=>{u.order={kind,x:clamp(x+(i%4)*.55,1,30),y:clamp(y+Math.floor(i/4)*.55,1,30)};u.path=null;u.target=null;});return ok(kind==='hold'?'Mantener posición.':kind==='attack'?'Avanzar y atacar.':'Orden de movimiento recibida.');}
function actorStats(a){return a.type in UNITS?unitStats(a.type,a.level):{...BUILDINGS[a.type],...buildingStats(a.type,a.level),damage:a.attack||0,speed:0,pop:0,interval:BUILDINGS[a.type].interval||1.5,armor:0};}
const dist=(a,b)=>Math.max(0,Math.hypot(a.x-b.x,a.y-b.y)-(b.type in BUILDINGS?BUILDINGS[b.type].size*.48:0));
function center(b){return b.type in BUILDINGS?{...b,x:b.x+BUILDINGS[b.type].size/2,y:b.y+BUILDINGS[b.type].size/2}:b;}
function canHit(a,b){const u=actorStats(a),v=UNITS[b.type];return !(v?.flying&&!u.flying&&u.range<2&&!u.air);}
function blocked(b,x,y,except=null){if(x<1||y<1||x>30||y>30)return true;return b.buildings.some(v=>v.hp>0&&v.id!==except&&x>=v.x-.15&&x<=v.x+BUILDINGS[v.type].size+.15&&y>=v.y-.15&&y<=v.y+BUILDINGS[v.type].size+.15);}
function navigate(b,u,target,speed,dt){const dx=target.x-u.x,dy=target.y-u.y,d=Math.hypot(dx,dy);if(d<.1)return false;let vx=dx/d,vy=dy/d,step=Math.min(speed*dt,d),nx=u.x+vx*step,ny=u.y+vy*step;const flying=UNITS[u.type].flying;if(!flying&&blocked(b,nx,ny)){let found=false;for(const angle of[.65,-.65,1.2,-1.2,1.57,-1.57,2.2,-2.2]){const xx=u.x+(vx*Math.cos(angle)-vy*Math.sin(angle))*step,yy=u.y+(vx*Math.sin(angle)+vy*Math.cos(angle))*step;if(!blocked(b,xx,yy)){nx=xx;ny=yy;found=true;break;}}if(!found)return false;}u.x=nx;u.y=ny;u.facing=Math.atan2(vx,vy);return true;}
function harm(s,b,a,target,st){const mult=a.side==='enemy'?(a.damageScale||DIFFICULTIES[s.difficulty].damage):1,def=actorStats(target),damage=Math.max(2,st.damage*mult*(UNITS[target.type]?.heavy?st.vsHeavy||1:1)*(UNITS[target.type]?.flying?st.vsAir||1:1)*(target.type in BUILDINGS?st.siege||1:1)-(def.armor||0));target.hp=Math.max(0,target.hp-damage);if(target.hp<=0&&target.type in UNITS){if(target.side==='enemy')s.stats.kills++;else{s.stats.lost++;log(s,UNITS[target.type].name+' ha caído.');}}if(st.splash)for(const other of b.units)if(other!==target&&other.hp>0&&other.side!==a.side&&dist(center(target),other)<st.splash){other.hp=Math.max(0,other.hp-damage*.4);if(other.hp<=0){if(other.side==='enemy')s.stats.kills++;else{s.stats.lost++;log(s,UNITS[other.type].name+' ha caído.');}}}b.effects.push({id:b.serial++,x:a.x,y:a.y,tx:center(target).x,ty:center(target).y,weapon:st.weapon||'arrow',side:a.side,at:b.elapsed});if(b.effects.length>100)b.effects.splice(0,b.effects.length-100);}
export function tickBattle(s,dt){const b=s.battle;if(!b)return;b.elapsed+=dt;b.effects=b.effects.filter(e=>b.elapsed-e.at<.45);const alive=b.units.filter(u=>u.hp>0);for(const u of alive){const st=actorStats(u);u.moving=false;u.cooldown=Math.max(0,u.cooldown-dt);if(st.heal){const patient=alive.filter(t=>t.side===u.side&&t.hp<t.maxHp).sort((a,c)=>(a.hp/a.maxHp)-(c.hp/c.maxHp))[0];if(patient){if(dist(u,patient)<=st.range&&u.cooldown<=0){patient.hp=Math.min(patient.maxHp,patient.hp+st.heal);u.cooldown=st.interval;}else if(dist(u,patient)>st.range)u.moving=navigate(b,u,patient,st.speed,dt);}continue;}
 let targets=alive.filter(v=>v.side!==u.side&&canHit(u,v)),near=targets.filter(t=>dist(u,t)<7.5).sort((a,c)=>dist(u,a)-dist(u,c));let target=near[0];if(u.order?.kind==='move'){u.moving=navigate(b,u,u.order,st.speed,dt);if(Math.hypot(u.x-u.order.x,u.y-u.order.y)<.3)u.order={kind:'hold',x:u.x,y:u.y};if(!target||dist(u,target)>st.range)continue;}if(!target&&u.order?.kind==='hold')continue;
 if(!target&&u.order?.kind==='attack'){const local=b.buildings.filter(t=>t.hp>0&&t.side!==u.side&&dist(u,center(t))<7.5).sort((a,c)=>dist(u,center(a))-dist(u,center(c)));target=local[0];if(!target){u.moving=navigate(b,u,u.order,st.speed,dt);if(Math.hypot(u.x-u.order.x,u.y-u.order.y)<.3)u.order={kind:'hold',x:u.x,y:u.y};continue;}}
 if(!target){const bases=b.buildings.filter(t=>t.hp>0&&t.side!==u.side);target=bases.sort((a,c)=>dist(u,center(a))-dist(u,center(c)))[0]||targets.sort((a,c)=>dist(u,a)-dist(u,c))[0];}if(!target)continue;const t=center(target),d=dist(u,t);if(d<=st.range+.15&&u.cooldown<=0){harm(s,b,u,target,st);u.cooldown=st.interval;}else if(d>st.range&&u.order?.kind!=='move'&&u.order?.kind!=='hold')u.moving=navigate(b,u,t,st.speed,dt);}
 for(const tower of b.buildings.filter(x=>x.hp>0&&BUILDINGS[x.type].attack)){tower.cooldown=Math.max(0,(tower.cooldown||0)-dt);if(tower.cooldown>0)continue;const st=actorStats(tower),from=center(tower),targets=alive.filter(u=>u.hp>0&&u.side!==tower.side&&canHit(tower,u)&&dist(from,u)<=st.range).sort((a,c)=>dist(from,a)-dist(from,c));if(targets.length){harm(s,b,from,targets[0],st);tower.cooldown=st.interval;}}
 // Separate allies so a formation reads as individual soldiers and vehicles.
 for(let i=0;i<alive.length;i++)for(let j=i+1;j<alive.length;j++){const a=alive[i],c=alive[j];if(a.side!==c.side)continue;const dx=a.x-c.x,dy=a.y-c.y,d=Math.hypot(dx,dy);if(d>0&&d<.4){const p=(.4-d)*.22;a.x=clamp(a.x+dx/d*p,1,30);a.y=clamp(a.y+dy/d*p,1,30);c.x=clamp(c.x-dx/d*p,1,30);c.y=clamp(c.y-dy/d*p,1,30);}}
 if(b.kind==='raid'){if(!b.units.some(u=>u.side==='enemy'&&u.hp>0)||b.buildings.find(t=>t.type==='hq')?.hp<=0||b.elapsed>=b.limit)finishBattle(s);}else if(!b.buildings.some(v=>v.hp>0)||(!b.reserve.length&&!b.units.some(u=>u.side==='player'&&u.hp>0))||b.elapsed>=b.limit)finishBattle(s);
}
export function startRaid(s){if(s.battle)return false;const level=hqLevel(s),units=[],types=Object.values(UNITS).filter(u=>u.hq<=Math.max(1,level)&&!u.heal);for(let i=0;i<3+level;i++){const type=types[Math.floor(rand(i,33,s.seed+Math.floor(s.time))*types.length)].id,u=makeUnit(s,type,1);Object.assign(u,{side:'enemy',x:3+i%3,y:10+Math.floor(i/3)*1.3,damageScale:DIFFICULTIES[s.difficulty].damage*.8,order:{kind:'assault',x:15,y:15}});units.push(u);}s.army.forEach((u,i)=>Object.assign(u,{side:'player',x:12+i%5*.8,y:20+Math.floor(i/5)*.8,order:{kind:'assault',x:8,y:15},cooldown:0}));s.battle={kind:'raid',name:'Defiende tu base',seed:s.seed,elapsed:0,limit:150,buildings:s.buildings.map(b=>({...b,...buildingStats(b.type,b.level),maxHp:buildingStats(b.type,b.level).hp,hp:b.hp,side:'player'})),units:[...s.army,...units],reserve:[],initialBuildings:s.buildings.length,reward:{gold:150+level*50},effects:[],serial:0};s.army=[];log(s,GAME.enemy+' ataca tu base.');return true;}
export function finishBattle(s){const b=s.battle;if(!b)return fail('No hay batalla.');const destroyed=b.buildings.filter(x=>x.hp<=0).length,ratio=destroyed/b.initialBuildings,hq=b.buildings.find(x=>x.type==='hq'),victory=b.kind==='raid'?hq?.hp>0&&!b.units.some(u=>u.side==='enemy'&&u.hp>0):hq?.hp<=0,stars=b.kind==='attack'?(victory?1:0)+(ratio>=.5?1:0)+(ratio===1?1:0):victory?3:0;let reward={};
 const survivors=b.units.filter(u=>u.side==='player'&&u.hp>0);for(const u of[...survivors,...b.reserve]){u.hp=Math.min(u.hp,u.maxHp);delete u.order;delete u.side;delete u.path;u.cooldown=0;s.army.push(u);}
 if(b.kind==='attack'){if(victory){const first=!s.completed[b.index];s.completed[b.index]=Math.max(s.completed[b.index]||0,stars);const factor=first?1:.25;reward=Object.fromEntries(Object.entries(b.reward).map(([k,v])=>[k,Math.round(v*factor)]));credit(s,reward);s.stats.wins++;s.xp+=first?180+b.index*40:30;log(s,'Victoria en '+b.name+' · '+stars+' estrellas.');}else log(s,'Retirada de '+b.name+'. Los supervivientes regresan.');}
 else{for(const original of s.buildings){const battle=b.buildings.find(x=>x.id===original.id);if(battle)original.hp=Math.max(0,battle.hp);}if(victory){reward=b.reward;credit(s,reward);s.xp+=80;log(s,'La defensa resistió el ataque.');}else{for(const k of RESOURCE_KEYS)s.resources[k]=Math.floor(s.resources[k]*.85);log(s,'Base saqueada: perdiste el 15% de tus reservas. Reconstruye y refuerza las defensas.');}}
 s.lastBattle={name:b.name,kind:b.kind,victory,stars,destroyed,total:b.initialBuildings,reward,survivors:survivors.length,reserve:b.reserve.length,lost:b.units.filter(u=>u.side==='player'&&u.hp<=0).length};s.battle=null;s.nextRaid=s.time+(600+hqLevel(s)*45)*DIFFICULTIES[s.difficulty].raid;return ok(victory?'Victoria. Tus supervivientes vuelven a casa.':'Retirada completada.');
}
export function step(s,dt){if(!Number.isFinite(dt)||dt<=0)return;dt=Math.min(dt,1);tickEconomy(s,dt);if(s.battle)tickBattle(s,dt);else if(s.time>=s.nextRaid)startRaid(s);}
export function encode(s,now=Date.now()){return JSON.stringify({...s,savedAt:now});}
export function decode(raw,now=Date.now(),offline=true){if(typeof raw!=='string'||raw.length>3000000)throw Error('Archivo de guardado demasiado grande.');const s=JSON.parse(raw);if(!s||s.version!==1||s.game!==GAME.id)throw Error('La copia pertenece a otro juego o a una versión incompatible.');if(!Number.isFinite(s.time)||s.time<0||!Number.isInteger(s.seed)||!Number.isInteger(s.serial)||s.serial<1)throw Error('Reloj o semilla no válidos.');if(!Object.hasOwn(DIFFICULTIES,s.difficulty))throw Error('Dificultad no válida.');for(const k of RESOURCE_KEYS)if(!Number.isFinite(s.resources?.[k])||s.resources[k]<0||s.resources[k]>1e12)throw Error('Inventario no válido.');if(!Array.isArray(s.buildings)||s.buildings.length>300||!Array.isArray(s.army)||s.army.length>1000||!Array.isArray(s.training)||s.training.length>300)throw Error('Catálogo del guardado no válido.');const validId=id=>typeof id==='string'&&/^[A-Za-z][A-Za-z0-9_-]{0,70}$/.test(id);const ids=new Set();for(const b of s.buildings){if(!validId(b.id)||!Object.hasOwn(BUILDINGS,b.type)||!Number.isInteger(b.level)||b.level<1||b.level>10||!Number.isInteger(b.x)||!Number.isInteger(b.y)||b.x<0||b.y<0||b.x+BUILDINGS[b.type].size>SIZE||b.y+BUILDINGS[b.type].size>SIZE||!Number.isFinite(b.hp)||b.hp<0||!Number.isFinite(b.stored)||b.stored<0||ids.has(b.id))throw Error('Edificio no válido.');ids.add(b.id);if(b.job&&(!['build','upgrade','repair'].includes(b.job.kind)||!Number.isFinite(b.job.ends)||!Number.isFinite(b.job.started)||b.job.ends<b.job.started))throw Error('Obra no válida.');}if(s.buildings.filter(b=>b.type==='hq').length!==1)throw Error('Falta el edificio principal.');for(const u of s.army)if(!validId(u.id)||!Object.hasOwn(UNITS,u.type)||!Number.isFinite(u.hp)||u.hp<=0||!Number.isFinite(u.maxHp)||u.maxHp<=0||!Number.isInteger(u.level)||u.level<1||u.level>5)throw Error('Ejército no válido.');for(const t of s.training)if(!validId(t.id)||!Object.hasOwn(UNITS,t.type)||!Number.isFinite(t.ends)||!Number.isFinite(t.started)||!Number.isInteger(t.level)||t.level<1||t.level>5||!ids.has(t.building))throw Error('Cola de entrenamiento no válida.');if(!s.stats||!Array.isArray(s.claimed)||!Array.isArray(s.cleared)||s.cleared.length>SIZE*SIZE||!Array.isArray(s.log)||!s.research||!s.completed||!s.settings)throw Error('Copia incompleta.');for(const[k,v]of Object.entries(s.research))if(!Object.hasOwn(UNITS,k)||!Number.isInteger(v)||v<1||v>5)throw Error('Investigación no válida.');if(!s.alliances||typeof s.alliances!=='object')throw Error('Diplomacia no válida.');for(const[id,p]of Object.entries(s.alliances))if(!ALLIES.some(a=>a.id===id)||!Number.isInteger(p.reputation)||p.reputation<0||p.reputation>1000000||!Number.isFinite(p.next))throw Error('Pacto no válido.');if(s.study&&(!Object.hasOwn(UNITS,s.study.type)||!Number.isFinite(s.study.ends)||!Number.isInteger(s.study.level)||s.study.level<2||s.study.level>5))throw Error('Investigación pendiente no válida.');if(s.battle){if(!['attack','raid'].includes(s.battle.kind)||!Array.isArray(s.battle.units)||!Array.isArray(s.battle.buildings)||!Array.isArray(s.battle.reserve)||s.battle.units.length>1000||!Number.isFinite(s.battle.elapsed))throw Error('Batalla no válida.');for(const u of[...s.battle.units,...s.battle.reserve])if(!Object.hasOwn(UNITS,u.type)||!Number.isFinite(u.hp)||!Number.isFinite(u.maxHp)||!Number.isInteger(u.level)||!Number.isFinite(u.x??0)||!Number.isFinite(u.y??0))throw Error('Combatiente no válido.');for(const b of s.battle.buildings)if(!Object.hasOwn(BUILDINGS,b.type)||!Number.isFinite(b.hp)||!Number.isFinite(b.x)||!Number.isFinite(b.y))throw Error('Base rival no válida.');}
 if(offline){const elapsed=clamp((now-(s.savedAt||now))/1000,0,8*3600);if(elapsed>5){tickEconomy(s,elapsed);s.nextRaid=Math.max(s.nextRaid,s.time+90);log(s,'Se completaron '+Math.floor(elapsed/60)+' minutos de producción y trabajos durante tu ausencia.');}}s.savedAt=now;return s;
}
